script:
(function () {
  'use strict';
  // Drawing down a savings account. Withdrawals are made f times a year starting on the first
  // withdrawal date (the balance entered is the balance on that day). After each withdrawal the
  // rest earns one period of interest at the rate per withdrawal period
  //   i = (1 + r / n)^(n / f) - 1   (rate compounded n times a year), or (1 + APY)^(1 / f) - 1.
  // The withdrawal can rise by g once a year (every f withdrawals).
  //   Set amount: run until the balance is used up (the last withdrawal takes what is left).
  //   Until a date: N = number of withdrawal dates from the first date to the end date. The
  //   balance left after the N-th withdrawal is linear in the first withdrawal w, so
  //   w = (E(0) - leave) / (E(0) - E(1)), with E(w) from the same simulation. With g = 0 this is the
  //   annuity-due payment w = (B - leave x v^(N-1)) x i / ((1 + i) x (1 - v^N)), v = 1 / (1 + i).
  // Checked in Node (b8pay/tests/sd.test.js): $25,000 at 4% compounded monthly, monthly until
  //   N = 60 -> $458.88 (closed form 25,000 x 0.0033333 / (1.0033333 x (1 - 1.0033333^-60)));
  //   0% and $500 a month from $25,000 -> 50 withdrawals; $10,000 at 0% for 10 yearly withdrawals ->
  //   $1,000; 5% APY yearly, $10,000, $1,000 a year -> 14 withdrawals, the last $257.86 (closed form
  //   10,000 x 1.05^13 - 1,050 x (1.05^13 - 1) / 0.05); a 3% raise solved for 60 months and then run
  //   as a set amount lasts exactly 60 withdrawals; interest-only withdrawal $25,000 x i / (1 + i) keeps
  //   the balance level forever; dates: Jan 31 + 1 month = Feb 28; 2026-11-01 to 2031-10-01 monthly
  //   = 60 withdrawals.
  var MAX_YEARS = 100;

  // --- calc start
  function periodRate(rate, compound, f) {
    if (compound === 'apy') return Math.pow(1 + rate, 1 / f) - 1;
    var n = parseInt(compound, 10);
    return Math.pow(1 + rate / n, n / f) - 1;
  }

  // Runs the drawdown. o: balance, i, f, w (first-year withdrawal), g, maxCount, stopWhenEmpty
  function simulate(o) {
    var bal = o.balance, total = 0, interest = 0, rows = [], count = 0, last = 0, w = o.w;
    var row = null;
    for (var k = 0; k < o.maxCount; k++) {
      if (k > 0 && k % o.f === 0) w *= 1 + o.g;
      if (k % o.f === 0) { row = { year: k / o.f + 1, first: k, withdrawn: 0, interest: 0, end: 0 }; rows.push(row); }
      var take = o.stopWhenEmpty ? Math.min(w, bal) : w;
      if (o.stopWhenEmpty && bal <= 0.005) { rows.pop(); break; }
      bal -= take; total += take; row.withdrawn += take; count++; last = take;
      if (o.stopWhenEmpty && bal <= 0.005) { bal = 0; row.end = 0; break; }
      if (o.noInterestAfter === k + 1) { row.end = bal; break; }
      var earned = bal * o.i;
      bal += earned; interest += earned; row.interest += earned; row.end = bal;
    }
    return { balance: bal, total: total, interest: interest, rows: rows, count: count, last: last };
  }

  // Set amount: how long it lasts.
  function fixedPlan(B, i, f, w, g) {
    var r = simulate({ balance: B, i: i, f: f, w: w, g: g, maxCount: f * MAX_YEARS, stopWhenEmpty: true });
    r.forever = r.balance > 0.005;
    return r;
  }

  // Until a date: first-year withdrawal that leaves `leave` after the N-th withdrawal.
  function datePlan(B, i, f, N, g, leave) {
    var base = { balance: B, i: i, f: f, g: g, maxCount: N, stopWhenEmpty: false, noInterestAfter: N };
    var e0 = simulate(Object.assign({}, base, { w: 0 })).balance;
    var e1 = simulate(Object.assign({}, base, { w: 1 })).balance;
    if (e0 - e1 <= 0 || leave > e0 + 0.005) return null;
    var w = (e0 - leave) / (e0 - e1);
    var r = simulate(Object.assign({}, base, { w: w }));
    r.w = w;
    return r;
  }

  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
    if (!m) return null;
    var d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
    return isNaN(d.getTime()) || d.getUTCDate() !== +m[3] ? null : d;
  }
  // Date of withdrawal k (0-based): month steps keep the start day, clamped to the month's end.
  function withdrawalDate(start, f, k) {
    if (f === 52 || f === 26) return new Date(start.getTime() + k * (f === 52 ? 7 : 14) * 86400000);
    var months = k * (12 / f), y = start.getUTCFullYear(), mo = start.getUTCMonth() + months;
    var ty = y + Math.floor(mo / 12), tm = mo % 12;
    var dim = new Date(Date.UTC(ty, tm + 1, 0)).getUTCDate();
    return new Date(Date.UTC(ty, tm, Math.min(start.getUTCDate(), dim)));
  }
  function countDates(start, end, f) {
    var n = 0, cap = f * MAX_YEARS;
    while (n < cap && withdrawalDate(start, f, n).getTime() <= end.getTime()) n++;
    return n;
  }
  // --- calc end

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var shortDate = new Intl.DateTimeFormat('en-US', { year: 'numeric', month: 'short', day: 'numeric', timeZone: 'UTC' });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 2, maximumFractionDigits: 3 });
  var FREQ_NAME = { 52: 'weekly', 26: 'every-two-weeks', 12: 'monthly', 4: 'quarterly', 1: 'yearly' };

  function el(id) { return document.getElementById(id); }
  function num(id) { var v = parseFloat(el(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { var e = el(id); if (e) e.textContent = text; }
  function fmt(v) { return money.format(Math.abs(v) < 0.005 ? 0 : v); }

  function span(count, f) {
    if (f === 52 || f === 26) {
      var yrs = count / f;
      return yrs < 1 ? count + (f === 52 ? ' weeks' : ' two-week periods') : 'about ' + (Math.round(yrs * 10) / 10) + ' years';
    }
    var months = count * 12 / f, y = Math.floor(months / 12), m = months % 12;
    var parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(', ') || '0 months';
  }

  function update() {
    var mode = el('sdMode').value === 'date' ? 'date' : 'fixed';
    el('sdFixedGroup').hidden = mode !== 'fixed';
    el('sdDateGroup').hidden = mode !== 'date';
    var B = num('sdBalance'), rate = num('sdRate'), compound = el('sdCompound').value,
        f = parseInt(el('sdFreq').value, 10), g = num('sdRaise'), w = num('sdAmount'), leave = num('sdLeave');
    if ([52, 26, 12, 4, 1].indexOf(f) < 0) f = 12;
    var start = parseDate(el('sdStart').value), end = parseDate(el('sdEnd').value);
    var error = el('sdError'), msg = '';
    if ([B, rate, g].some(function (v) { return !isFinite(v) || v < 0; }) || B <= 0 || B > 1e10 || rate > 30 || g > 20) {
      msg = 'Enter a savings balance above $0, an interest rate from 0 to 30% and a yearly raise from 0 to 20%.';
    } else if (!start) {
      msg = 'Enter the date of your first withdrawal.';
    } else if (mode === 'fixed' && (!isFinite(w) || w <= 0 || w > 1e10)) {
      msg = 'Enter a withdrawal amount above $0.';
    } else if (mode === 'date' && !end) {
      msg = 'Enter the date of your last withdrawal.';
    } else if (mode === 'date' && end.getTime() < start.getTime()) {
      msg = 'The last withdrawal date must be on or after the first withdrawal date.';
    } else if (mode === 'date' && (!isFinite(leave) || leave < 0 || leave > 1e10)) {
      msg = 'Enter a balance to leave of $0 or more.';
    }
    var i = periodRate(rate / 100, compound, f), N = 0, r = null;
    if (!msg && mode === 'date') {
      N = countDates(start, end, f);
      r = datePlan(B, i, f, N, g / 100, leave);
      if (!r) msg = 'Your savings cannot grow to the balance you want to leave by that date, even with no withdrawals.';
    }
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }

    var notes = [];
    if (mode === 'fixed') {
      r = fixedPlan(B, i, f, w, g / 100);
      set('sdMainLabel', 'Your savings last');
      set('sdSecondLabel', 'Last withdrawal');
      if (r.forever) {
        set('sdMain', MAX_YEARS + '+ years');
        set('sdSecond', 'Not reached');
        notes.push('Interest keeps pace with your withdrawals, so the account is not used up within ' + MAX_YEARS + ' years. The totals cover those ' + MAX_YEARS + ' years.');
      } else {
        set('sdMain', span(r.count, f));
        set('sdSecond', shortDate.format(withdrawalDate(start, f, r.count - 1)));
      }
      set('sdFinal', r.count ? fmt(r.last) : '–');
    } else {
      set('sdMainLabel', 'You can withdraw');
      set('sdSecondLabel', 'Last withdrawal');
      set('sdMain', fmt(r.w) + ' ' + FREQ_NAME[f]);
      set('sdSecond', shortDate.format(withdrawalDate(start, f, N - 1)));
      set('sdFinal', fmt(r.last));
      if (g > 0) notes.push('This is the first year\'s amount. It rises by ' + g + '% on each anniversary of your first withdrawal.');
      if (leave > 0) notes.push(fmt(r.balance) + ' stays in the account after the last withdrawal.');
    }
    set('sdTotal', fmt(r.total));
    set('sdInterest', fmt(r.interest));
    set('sdCount', String(r.count) + ' (' + FREQ_NAME[f] + ')');
    set('sdInterestOnly', fmt(B * i / (1 + i)));
    set('sdApy', pct.format(Math.pow(1 + i, f) - 1));
    if (g > 0 && mode === 'fixed') notes.push('Your withdrawal rises by ' + g + '% a year, so the final full withdrawal is larger than the first.');
    var noteEl = el('sdNote');
    noteEl.hidden = notes.length === 0;
    noteEl.textContent = notes.join(' ');

    var body = el('sdSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [String(row.year), shortDate.format(withdrawalDate(start, f, row.first)), fmt(row.withdrawn), fmt(row.interest), fmt(row.end)].forEach(function (t) {
        var td = document.createElement('td'); td.textContent = t; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('sdForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
